INSERT INTO `front_cms_menu_items` (`id`, `menu_id`, `menu`, `page_id`, `parent_id`, `ext_url`, `open_new_tab`, `ext_url_link`, `slug`, `weight`, `publish`, `description`, `is_active`, `content_heading`, `menu_description`, `image_position`, `media_gallery_id`, `created_at`) VALUES (4, 1, 'Admission', 0, 0, NULL, NULL, 'http://yourschoolurl.com/online_admission', 'admission', 2, 0, NULL, 'no', 'Admission Content', '<p style=\"box-sizing: border-box; margin: 0px 0px 10px; font-family: &quot;Open Sans&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">Established in 1985, BBC Senior Secondary School has been at the forefront of providing quality education to students from diverse backgrounds. Our institution is committed to holistic development, ensuring that each student achieves their full potential.</p>\r\n\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; font-family: &quot;Open Sans&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">We offer a comprehensive curriculum that balances academic rigor with co-curricular activities, preparing students for higher education and successful careers. Our experienced faculty members are dedicated to creating a stimulating learning environment.</p>\r\n\r\n<p style=\"box-sizing: border-box; margin: 0px 0px 10px; font-family: &quot;Open Sans&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">Our campus features state-of-the-art facilities including well-equipped laboratories, a comprehensive library, sports complexes, and technology-enabled classrooms.</p>\r\n', 0, 8, '2026-02-25 19:59:29');
